"use client"
import * as React from "react"
import { AnimatePresence, LayoutGroup, motion, useMotionTemplate, useMotionValue, useReducedMotion, useSpring, useTransform } from "framer-motion"
import { Search, X } from "lucide-react"
import { cn } from "@/lib/utils"

export interface FaqItem { id: string; question: string; answer: string }

export interface FaqLiquidAccordionProps {
  items: FaqItem[]
  title?: string
  subtitle?: string
  /** Id of the item that starts open. */
  defaultOpenId?: string
  className?: string
}

const CORAL = "#ff6b57"
const GRADIENT = `linear-gradient(120deg,var(--primary),${CORAL})`
const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")

/** Wraps matches in a marker that paints itself in with a sweep. */
function Marked({ text, terms }: { text: string; terms: string[] }) {
  const reduce = useReducedMotion()
  if (!terms.length) return <>{text}</>
  const re = new RegExp(`(${terms.map(esc).join("|")})`, "ig")
  return (
    <>
      {text.split(re).map((part, i) =>
        i % 2 ? (
          <motion.mark key={i} initial={{ backgroundSize: reduce ? "100% 100%" : "0% 100%" }} animate={{ backgroundSize: "100% 100%" }} transition={{ duration: 0.45, delay: 0.05 * (i / 2) }}
            className="rounded-[3px] bg-transparent px-0.5 text-foreground [box-decoration-break:clone]" style={{ backgroundImage: `linear-gradient(90deg,color-mix(in oklab,${CORAL} 55%,transparent),color-mix(in oklab,var(--primary) 40%,transparent))`, backgroundRepeat: "no-repeat" }}>
            {part}
          </motion.mark>
        ) : <React.Fragment key={i}>{part}</React.Fragment>,
      )}
    </>
  )
}

/** Words fade in out of a blur, one after another. */
function Words({ text, terms }: { text: string; terms: string[] }) {
  const reduce = useReducedMotion()
  const words = text.split(" ")
  if (reduce) return <Marked text={text} terms={terms} />
  return (
    <>
      {words.map((w, i) => (
        <motion.span key={i} className="inline-block" initial={{ opacity: 0, y: 6, filter: "blur(6px)" }} animate={{ opacity: 1, y: 0, filter: "blur(0px)" }} transition={{ duration: 0.35, delay: 0.18 + i * 0.012 }}>
          <Marked text={w} terms={terms} />&nbsp;
        </motion.span>
      ))}
    </>
  )
}

export function FaqLiquidAccordion({ items, title = "Questions, answered", subtitle = "Type to find the one you need.", defaultOpenId, className }: FaqLiquidAccordionProps) {
  const reduce = useReducedMotion()
  const uid = React.useId()
  const [open, setOpen] = React.useState<string | null>(defaultOpenId ?? null)
  const [q, setQ] = React.useState("")
  const terms = q.trim().split(/\s+/).filter((t) => t.length > 0)
  const shown = terms.length ? items.filter((it) => terms.every((t) => new RegExp(esc(t), "i").test(it.question + " " + it.answer))) : items
  const heads = React.useRef<Record<string, HTMLButtonElement | null>>({})

  // soft light that follows the cursor, plus parallax blobs
  const mx = useMotionValue(0.5), my = useMotionValue(0.5)
  const px = useMotionValue(-300), py = useMotionValue(-300)
  const ax = useSpring(useTransform(mx, [0, 1], [30, -30]), { stiffness: 60, damping: 20 }), ay = useSpring(useTransform(my, [0, 1], [30, -30]), { stiffness: 60, damping: 20 })
  const glow = useMotionTemplate`radial-gradient(260px circle at ${px}px ${py}px, color-mix(in oklab, var(--primary) 14%, transparent), transparent 70%)`

  const key = (e: React.KeyboardEvent, i: number) => {
    const ids = shown.map((s) => s.id)
    const to = e.key === "ArrowDown" ? i + 1 : e.key === "ArrowUp" ? i - 1 : e.key === "Home" ? 0 : e.key === "End" ? ids.length - 1 : null
    if (to === null) return
    e.preventDefault(); heads.current[ids[(to + ids.length) % ids.length]]?.focus()
  }

  return (
    <div className={cn("relative w-full max-w-xl", className)}>
      <motion.div aria-hidden className="pointer-events-none absolute -inset-3 rounded-[2rem] blur-2xl" style={{ background: `conic-gradient(from 120deg,var(--primary),${CORAL},#f5a3ff,var(--primary))` }}
        animate={reduce ? { opacity: 0.2 } : { opacity: [0.15, 0.35, 0.15], rotate: [0, 8, 0] }} transition={{ duration: 7, repeat: Infinity, ease: "easeInOut" }} />
      <section aria-label={title} className="relative overflow-hidden rounded-2xl border border-border bg-card p-5 text-foreground shadow-[0_40px_70px_-35px_color-mix(in_oklab,var(--primary)_55%,transparent)] sm:p-6"
        onPointerMove={(e) => { const b = e.currentTarget.getBoundingClientRect(); mx.set((e.clientX - b.left) / b.width); my.set((e.clientY - b.top) / b.height); px.set(e.clientX - b.left); py.set(e.clientY - b.top) }}>
        <div aria-hidden className="pointer-events-none absolute inset-0 overflow-hidden">
          <motion.div className="absolute -right-12 -top-16 size-52 rounded-full blur-3xl" style={{ x: ax, y: ay, background: `color-mix(in oklab,${CORAL} 28%,transparent)` }} />
          <motion.div className="absolute -bottom-20 -left-10 size-52 rounded-full blur-3xl" style={{ x: ay, y: ax, background: "color-mix(in oklab,var(--primary) 26%,transparent)" }} />
          {!reduce && <motion.div className="absolute inset-0" style={{ background: glow }} />}
        </div>

        <header className="relative">
          <h2 className="text-xl font-semibold leading-tight tracking-tight">{title}</h2>
          <p className="mt-1 text-sm text-muted-foreground">{subtitle}</p>
        </header>

        <div className="relative mt-4">
          <label htmlFor={`${uid}-s`} className="sr-only">Search questions</label>
          <Search className="pointer-events-none absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" aria-hidden />
          <input id={`${uid}-s`} type="search" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search, for example “refund”" autoComplete="off"
            className="block min-h-12 w-full rounded-xl border border-border bg-background pl-10 pr-11 text-sm outline-none transition-shadow placeholder:text-muted-foreground focus:border-primary focus:shadow-[0_0_0_4px_color-mix(in_oklab,var(--primary)_22%,transparent)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring [&::-webkit-search-cancel-button]:hidden" />
          <AnimatePresence>
            {q && <motion.button type="button" onClick={() => setQ("")} aria-label="Clear search" initial={{ opacity: 0, scale: 0.5, rotate: -90 }} animate={{ opacity: 1, scale: 1, rotate: 0 }} exit={{ opacity: 0, scale: 0.5 }}
              className="absolute right-1 top-1/2 grid size-11 -translate-y-1/2 place-items-center rounded-lg text-muted-foreground outline-none hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"><X className="size-4" aria-hidden /></motion.button>}
          </AnimatePresence>
        </div>
        <p aria-live="polite" className="relative mt-2 h-5 text-xs text-muted-foreground">
          {terms.length ? (shown.length ? <><span className="font-semibold text-foreground">{shown.length}</span> of {items.length} questions match</> : "Nothing matches yet") : `${items.length} questions`}
        </p>

        <LayoutGroup>
          <motion.ul layout className="relative mt-1 space-y-2">
            <AnimatePresence initial={false} mode="popLayout">
              {shown.map((it, i) => {
                const isOpen = open === it.id
                return (
                  <motion.li key={it.id} layout="position" initial={{ opacity: 0, y: reduce ? 0 : 14, scale: reduce ? 1 : 0.97 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, scale: reduce ? 1 : 0.95 }}
                    transition={{ type: "spring", stiffness: 380, damping: 30, delay: reduce ? 0 : Math.min(i, 6) * 0.03 }}
                    className={cn("relative overflow-hidden rounded-xl border transition-colors", isOpen ? "border-primary/50 bg-muted/70" : "border-border bg-background/70 hover:border-primary/40")}>
                    {isOpen && <motion.span layoutId="faq-bar" className="absolute inset-y-0 left-0 w-1" style={{ background: GRADIENT }} transition={{ type: "spring", stiffness: 300, damping: 24 }} />}
                    <h3>
                      <button ref={(el) => { heads.current[it.id] = el }} type="button" aria-expanded={isOpen} aria-controls={`${uid}-${it.id}`} id={`${uid}-h-${it.id}`}
                        onClick={() => setOpen(isOpen ? null : it.id)} onKeyDown={(e) => key(e, i)}
                        className="flex min-h-14 w-full items-center justify-between gap-3 px-4 py-3 text-left text-[15px] font-medium outline-none focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring">
                        <span><Marked text={it.question} terms={terms} /></span>
                        <motion.span aria-hidden className="relative grid size-8 shrink-0 place-items-center rounded-full text-white" style={{ background: GRADIENT }}
                          animate={{ rotate: isOpen ? 135 : 0, scale: isOpen ? 1.12 : 1 }} transition={{ type: "spring", stiffness: 400, damping: 16 }}>
                          <span className="absolute h-0.5 w-3.5 rounded bg-white" /><span className="absolute h-3.5 w-0.5 rounded bg-white" />
                        </motion.span>
                      </button>
                    </h3>
                    <AnimatePresence initial={false}>
                      {isOpen && (
                        <motion.div key="p" id={`${uid}-${it.id}`} role="region" aria-labelledby={`${uid}-h-${it.id}`} className="relative overflow-hidden"
                          initial={{ height: 0 }} animate={{ height: "auto" }} exit={{ height: 0, transition: { duration: 0.22 } }}
                          transition={reduce ? { duration: 0.01 } : { type: "spring", stiffness: 260, damping: 20 }}>
                          {!reduce && (
                            <motion.div aria-hidden className="absolute inset-0" style={{ background: `radial-gradient(120% 100% at 0% 0%, color-mix(in oklab,${CORAL} 22%,transparent), color-mix(in oklab,var(--primary) 12%,transparent) 55%, transparent)` }}
                              initial={{ clipPath: "circle(0px at 32px 0px)" }} animate={{ clipPath: "circle(700px at 32px 0px)" }} exit={{ opacity: 0 }} transition={{ duration: 0.8, ease: [0.2, 0.8, 0.2, 1] }} />
                          )}
                          <p className="relative px-4 pb-4 pr-6 text-sm leading-relaxed text-muted-foreground"><Words text={it.answer} terms={terms} /></p>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </motion.li>
                )
              })}
            </AnimatePresence>
          </motion.ul>
        </LayoutGroup>

        <AnimatePresence>
          {terms.length > 0 && shown.length === 0 && (
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="relative mt-3 rounded-xl border border-dashed border-border p-6 text-center text-sm text-muted-foreground">
              No question mentions “{q}”. Try a shorter word, or <button type="button" onClick={() => setQ("")} className="min-h-11 font-medium text-primary underline underline-offset-4 outline-none focus-visible:outline-2 focus-visible:outline-ring">clear the search</button>.
            </motion.div>
          )}
        </AnimatePresence>
      </section>
    </div>
  )
}

const DEMO: FaqItem[] = [
  { id: "a", question: "How do I move my projects to a new account?", answer: "Open Settings, choose Transfer, and enter the email of the new owner. They get a link that stays valid for seven days, and nothing changes until they accept it." },
  { id: "b", question: "Can I work without an internet connection?", answer: "Yes. Recent projects are kept on your device and sync the next time you are online. Large media files are the only thing that needs a connection." },
  { id: "c", question: "What happens to my files if I cancel?", answer: "Your files stay available in read-only mode for 60 days, so you can export everything. After that they are deleted for good." },
  { id: "d", question: "Is there a discount for students or nonprofits?", answer: "Both groups get half off any plan. Send a short note with proof of status and we will apply the discount to your next invoice." },
  { id: "e", question: "How do I ask for a refund?", answer: "Write to support within 30 days of the charge. A person reads every request and replies within one working day." },
  { id: "f", question: "Who can see the things I upload?", answer: "Only people you invite. Links can be set to expire, and you can see who opened a file in the activity panel." },
  { id: "g", question: "Does it work on my phone?", answer: "The web version adapts to any screen size, and the mobile apps for iOS and Android add camera upload and offline mode." },
]

export default function Demo() {
  return (
    <div data-theme="plum" className="fixed inset-0 grid place-items-center overflow-auto bg-background p-6 text-foreground">
      <FaqLiquidAccordion items={DEMO} defaultOpenId="e" />
    </div>
  )
}

